func testAccAgentRegistrySkill_agentregistrySkillGcsExample(context map[string]interface{}) string {
	return acctest.Nprintf(`
data "google_project" "project" {}

resource "google_storage_bucket" "bucket" {
  name                        = "%{bucket_name}"
  location                    = "US"
  uniform_bucket_level_access = true
  force_destroy               = true
}

resource "google_storage_bucket_iam_member" "p4sa_reader" {
  bucket = google_storage_bucket.bucket.name
  role   = "roles/storage.objectViewer"
  member = "serviceAccount:service-${data.google_project.project.number}@gcp-sa-agentregistry.iam.gserviceaccount.com"
}

resource "google_storage_bucket_object" "object" {
  name    = "skill.zip"
  bucket  = google_storage_bucket.bucket.name
  content = base64decode("UEsDBBQAAAAAAEEQQRBjKl0XOwAAADsAAAAIAAAAU0tJTEwubWQtLS0KbmFtZTogdGVzdC1za2lsbApkZXNjcmlwdGlvbjogVGVzdCBza2lsbAotLS0KIyBUZXN0CnYwClBLAQIUAxQAAAAAAEEQQRBjKl0XOwAAADsAAAAIAAAAAAAAAAAAAQAAAAAAAABTS0lMTC5tZFBLBQYAAAAAAQABADYAAABhAAAAAAA=")
}

resource "google_agent_registry_skill" "default" {
  location     = "global"
  skill_id     = "%{skill_id}"
  target_state = "TARGET_STATE_DRAFT"
  type         = "SIMPLE"
  description  = "A test skill from GCS"
  display_name = "Test Skill GCS"
  scanning_config {
    policy = "DISABLED"
  }
  initial_revision {
    gcs_source {
      uri        = "gs://${google_storage_bucket.bucket.name}/${google_storage_bucket_object.object.name}"
      generation = tostring(google_storage_bucket_object.object.generation)
    }
  }
  depends_on = [google_storage_bucket_iam_member.p4sa_reader]
}
`, context)
}

func testAccCheckAgentRegistrySkillDestroyProducer(t *testing.T) func(s *terraform.State) error {
	return func(s *terraform.State) error {
		for name, rs := range s.RootModule().Resources {
			if rs.Type != "google_agent_registry_skill" {
				continue
			}
			if strings.HasPrefix(name, "data.") {
				continue
			}

			config := acctest.GoogleProviderConfig(t)
			url, err := tpgresource.ReplaceVarsForTest(config, rs, transport_tpg.BaseUrl(agentregistry.Product, config)+"projects/{{project}}/locations/{{location}}/skills/{{name}}")
			if err != nil {
				return err
			}

			billingProject := ""

			if config.BillingProject != "" {
				billingProject = config.BillingProject
			}

			_, err = transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
				Config:    config,
				Method:    "GET",
				Project:   billingProject,
				RawURL:    url,
				UserAgent: config.UserAgent,
			})
			if err == nil {
				return fmt.Errorf("AgentRegistrySkill still exists at %s", url)
			}
		}

		return nil
	}
}
